import React, { useEffect, useState, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { animalService, healthService, milkService, reproductionService } from '../services/api';
import toast from 'react-hot-toast';

const tabs = ['Özet', 'Sağlık', 'Süt', 'Üreme', 'Pasaport'];

export default function AnimalDetailPage() {
  const { id } = useParams();
  const { user } = useAuth();
  const navigate = useNavigate();
  const farmId = user?.farm_id;

  const [animal, setAnimal] = useState(null);
  const [healthRecords, setHealthRecords] = useState([]);
  const [milkRecords, setMilkRecords] = useState([]);
  const [reproductionRecords, setReproductionRecords] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('Özet');

  const loadAnimal = useCallback(async () => {
    setLoading(true);
    try {
      const [animalRes, healthRes, milkRes, reproRes] = await Promise.allSettled([
        animalService.get(id, farmId),
        healthService.list(farmId, { animal_id: id }),
        milkService.list(farmId, { animal_id: id }),
        reproductionService.list(farmId, { animal_id: id })
      ]);

      if (animalRes.status === 'fulfilled') setAnimal(animalRes.value.data);
      if (healthRes.status === 'fulfilled') setHealthRecords(healthRes.value.data.data || []);
      if (milkRes.status === 'fulfilled') setMilkRecords(milkRes.value.data.data || []);
      if (reproRes.status === 'fulfilled') setReproductionRecords(reproRes.value.data.data || []);
    } catch {
      toast.error('Hayvan yüklenemedi');
      navigate('/animals');
    } finally {
      setLoading(false);
    }
  }, [id, farmId, navigate]);

  useEffect(() => {
    loadAnimal();
  }, [loadAnimal]);

  if (loading) return (
    <div className="flex items-center justify-center h-64">
      <div className="w-8 h-8 border-4 border-green-600 border-t-transparent rounded-full animate-spin" />
    </div>
  );

  if (!animal) return null;

  const totalMilk = milkRecords.reduce((s, r) => s + parseFloat(r.quantity || 0), 0);
  const avgMilk = milkRecords.length ? (totalMilk / milkRecords.length).toFixed(2) : 0;

  return (
    <div className="space-y-4">
      {/* Geri + Başlık */}
      <div className="flex items-center gap-3">
        <button onClick={() => navigate('/animals')} className="text-gray-500 hover:text-gray-700">
          ← Hayvanlar
        </button>
        <h1 className="text-xl font-bold text-gray-800">{animal.name}</h1>
        <span className="font-mono text-sm bg-gray-100 px-2 py-0.5 rounded">{animal.code}</span>
      </div>

      {/* Profil kartı */}
      <div className="card">
        <div className="flex items-start gap-4">
          <div className="w-16 h-16 bg-green-100 rounded-xl flex items-center justify-center text-3xl flex-shrink-0">
            {animal.species === 'Keçi' ? '🐐' : animal.species === 'Koyun' ? '🐑' : animal.species === 'Sığır' ? '🐄' : animal.species === 'Manda' ? '🦬' : animal.species === 'Deve' ? '🐪' : '🐾'}
          </div>
          <div className="flex-1 grid grid-cols-2 md:grid-cols-4 gap-3 text-sm">
            <div><p className="text-gray-400">Tür / Irk</p><p className="font-medium">{animal.species}{animal.breed ? ` / ${animal.breed}` : ''}</p></div>
            <div><p className="text-gray-400">Doğum Tarihi</p><p className="font-medium">{animal.birth_date}</p></div>
            <div><p className="text-gray-400">Cinsiyet</p><p className="font-medium">{animal.gender === 'F' ? '♀ Dişi' : '♂ Erkek'}</p></div>
            <div><p className="text-gray-400">Canlı Ağırlık</p><p className="font-medium">{animal.current_weight ? `${animal.current_weight} kg` : '—'}</p></div>
            <div><p className="text-gray-400">Renk</p><p className="font-medium">{animal.color_description || '—'}</p></div>
            <div><p className="text-gray-400">Durum</p><p className="font-medium">{animal.status === 'active' ? '✅ Aktif' : animal.status}</p></div>
            <div><p className="text-gray-400">Süt Kaydı</p><p className="font-medium">{milkRecords.length} kayıt / Ort {avgMilk} L</p></div>
            <div><p className="text-gray-400">Sağlık Kaydı</p><p className="font-medium">{healthRecords.length} kayıt</p></div>
          </div>
        </div>
        {animal.notes && <p className="mt-3 text-sm text-gray-500 border-t pt-3">📝 {animal.notes}</p>}
      </div>

      {/* Tab bar */}
      <div className="flex gap-1 border-b border-gray-200">
        {tabs.map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors
              ${activeTab === tab
                ? 'border-green-600 text-green-700'
                : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}
          >
            {tab}
          </button>
        ))}
      </div>

      {/* Tab içerikleri */}
      {activeTab === 'Özet' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* Son sağlık kayıtları */}
          <div className="card">
            <h3 className="font-semibold text-gray-700 mb-3">Son Sağlık Kayıtları</h3>
            {healthRecords.length === 0 ? (
              <p className="text-gray-400 text-sm">Kayıt yok</p>
            ) : (
              <ul className="space-y-2">
                {healthRecords.slice(0, 4).map(h => (
                  <li key={h.id} className="flex items-start gap-2 text-sm">
                    <span className="text-lg">
                      {h.record_type === 'vaccination' ? '💉' : h.record_type === 'medication' ? '💊' : '🏥'}
                    </span>
                    <div>
                      <p className="font-medium text-gray-700">{h.description || h.medication_name || h.record_type}</p>
                      <p className="text-xs text-gray-400">{h.record_date}</p>
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </div>

          {/* Son süt kayıtları */}
          <div className="card">
            <h3 className="font-semibold text-gray-700 mb-3">Son Süt Kayıtları</h3>
            {milkRecords.length === 0 ? (
              <p className="text-gray-400 text-sm">Kayıt yok</p>
            ) : (
              <ul className="space-y-2">
                {milkRecords.slice(0, 6).map(m => (
                  <li key={m.id} className="flex items-center justify-between text-sm">
                    <span className="text-gray-600">{m.record_date}</span>
                    <span className="font-semibold text-blue-700">{m.quantity} L</span>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      )}

      {activeTab === 'Sağlık' && (
        <div className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-semibold text-gray-700">Tüm Sağlık Kayıtları ({healthRecords.length})</h3>
            <button onClick={() => navigate(`/health?animal_id=${id}`)} className="btn-primary text-sm py-1.5">
              + Kayıt Ekle
            </button>
          </div>
          {healthRecords.length === 0 ? (
            <p className="text-gray-400 py-6 text-center">Sağlık kaydı bulunamadı</p>
          ) : (
            <table className="w-full text-sm">
              <thead className="text-xs text-gray-500 uppercase border-b">
                <tr>
                  <th className="text-left pb-2">Tarih</th>
                  <th className="text-left pb-2">Tür</th>
                  <th className="text-left pb-2">Açıklama</th>
                  <th className="text-left pb-2">Maliyet</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {healthRecords.map(h => (
                  <tr key={h.id} className="hover:bg-gray-50">
                    <td className="py-2">{h.record_date}</td>
                    <td className="py-2">
                      <span className="badge badge-info text-xs">{h.record_type}</span>
                    </td>
                    <td className="py-2 text-gray-600">{h.description || h.medication_name || '—'}</td>
                    <td className="py-2 text-gray-600">{h.cost ? `₺${h.cost}` : '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {activeTab === 'Süt' && (
        <div className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-semibold text-gray-700">Süt Kayıtları</h3>
            <div className="text-sm text-gray-500">
              Toplam: <strong>{totalMilk.toFixed(1)} L</strong> · Ort: <strong>{avgMilk} L/gün</strong>
            </div>
          </div>
          {milkRecords.length === 0 ? (
            <p className="text-gray-400 py-6 text-center">Süt kaydı bulunamadı</p>
          ) : (
            <table className="w-full text-sm">
              <thead className="text-xs text-gray-500 uppercase border-b">
                <tr>
                  <th className="text-left pb-2">Tarih</th>
                  <th className="text-left pb-2">Saat</th>
                  <th className="text-left pb-2">Miktar (L)</th>
                  <th className="text-left pb-2">Notlar</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {milkRecords.map(m => (
                  <tr key={m.id} className="hover:bg-gray-50">
                    <td className="py-2">{m.record_date}</td>
                    <td className="py-2 text-gray-500">{m.record_time || '—'}</td>
                    <td className="py-2 font-semibold text-blue-700">{m.quantity}</td>
                    <td className="py-2 text-gray-500">{m.notes || '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {activeTab === 'Üreme' && (
        <div className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-semibold text-gray-700">Üreme Kayıtları ({reproductionRecords.length})</h3>
            <button onClick={() => navigate(`/reproduction?animal_id=${id}`)} className="btn-primary text-sm py-1.5">
              + Kayıt Ekle
            </button>
          </div>
          {reproductionRecords.length === 0 ? (
            <p className="text-gray-400 py-6 text-center">Üreme kaydı bulunamadı</p>
          ) : (
            <table className="w-full text-sm">
              <thead className="text-xs text-gray-500 uppercase border-b">
                <tr>
                  <th className="text-left pb-2">Tarih</th>
                  <th className="text-left pb-2">Kayıt Türü</th>
                  <th className="text-left pb-2">Detay / Doğum Tarihi</th>
                  <th className="text-left pb-2">Notlar</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {reproductionRecords.map(r => (
                  <tr key={r.id} className="hover:bg-gray-50">
                    <td className="py-2">{r.record_date}</td>
                    <td className="py-2">
                      <span className="badge badge-primary text-xs uppercase">{r.record_type}</span>
                    </td>
                    <td className="py-2 text-gray-600">
                      {r.expected_birth_date ? `Tahmini Doğum: ${r.expected_birth_date}` : (r.birth_date ? `Doğum: ${r.birth_date}` : '—')}
                    </td>
                    <td className="py-2 text-gray-500">{r.notes || '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {activeTab === 'Pasaport' && (
        <div className="card">
          <h3 className="font-semibold text-gray-700 mb-4">🪪 Hayvan Pasaportu</h3>
          {animal.passport ? (
            <div className="grid grid-cols-2 gap-4 text-sm">
              <div><p className="text-gray-400">HUBIS No</p><p className="font-mono font-medium">{animal.passport.national_id || '—'}</p></div>
              <div><p className="text-gray-400">Kayıt No</p><p className="font-mono font-medium">{animal.passport.registration_number || '—'}</p></div>
              <div><p className="text-gray-400">Küpe Etiketi</p><p className="font-mono font-medium">{animal.passport.ear_tag || animal.code}</p></div>
              <div><p className="text-gray-400">Mikroçip</p><p className="font-mono font-medium">{animal.passport.microchip_number || '—'}</p></div>
              <div><p className="text-gray-400">Durum</p><p className="font-medium">{animal.passport.status === 'active' ? '✅ Aktif' : '—'}</p></div>
            </div>
          ) : (
            <p className="text-gray-400">Pasaport bilgisi bulunamadı</p>
          )}
        </div>
      )}
    </div>
  );
}